-- Real database assertions; every fixture is rolled back. No provider is called.
begin;
do $$
declare owner_id uuid; other_id uuid:=gen_random_uuid(); fixture text:='quick:db-'||substr(md5(random()::text),1,12);
 payment1 text:='91'||floor(extract(epoch from now())*1000)::bigint::text;
 payment2 text:='92'||floor(extract(epoch from now())*1000)::bigint::text;
 order_id uuid:=gen_random_uuid(); original_body text; point text; p jsonb; paid jsonb; result jsonb; before_count integer; denied boolean; name text;
begin
 select id into strict owner_id from auth.users order by created_at limit 1;
 foreach name in array array['commerce_products','commerce_settings','commerce_product_history','commerce_upgrade_credits','commerce_conversion_outbox'] loop
  assert not has_table_privilege('anon','public.'||name,'select'),name||' anon private';
  assert not has_table_privilege('authenticated','public.'||name,'insert'),name||' authenticated cannot write';
  assert (select relrowsecurity from pg_class where oid=('public.'||name)::regclass),name||' RLS';
 end loop;
 assert not has_function_privilege('authenticated','public.commerce_save_product(uuid,jsonb,integer)','execute');
 assert (select not sales_enabled and not credit_enabled from public.commerce_settings where id='global');
 select to_jsonb(c) into p from public.commerce_products c where fulfillment_kind='document' limit 1;
 p:=p||jsonb_build_object('item_id',fixture,'title','Database fixture');
 result:=public.commerce_save_product(owner_id,p,0);
 assert (result->>'revision')::integer=1;
 original_body:=result->>'body';
 perform public.commerce_save_product(owner_id,p||jsonb_build_object('body','Nova versão de teste protegida'),1);
 assert (select snapshot->>'body'=original_body from public.commerce_product_history where item_id=fixture and revision=1),'original delivery archived';
 denied:=false;begin perform public.commerce_save_product(owner_id,p,0);exception when others then denied:=true;end;assert denied,'stale revision rejected';
 denied:=false;begin perform public.commerce_save_product(owner_id,p||jsonb_build_object('target_id','different'),2);exception when others then denied:=true;end;assert denied,'delivery identity immutable';
 paid:=jsonb_build_object('provider_payment_id',payment1,'user_id',owner_id,'order_id',null,'item_id',fixture,'kind','single','status','approved','amount_cents',490,'refunded_cents',0,'provider_fee_cents',30,'approved_at',now(),'created_at',now(),'provider_updated_at',now(),'environment','test');
 perform public.analytics_record_payment(paid);perform public.analytics_record_payment(paid);
 insert into public.user_purchases(user_id,item_id,item_type,status,amount_cents,provider,provider_payment_id,purchased_at) values(owner_id,fixture,'card','paid',490,'mercadopago',payment1,now());
 assert (select count(*)=1 from public.analytics_payments where provider_payment_id=payment1),'duplicate financial event';
 assert (select count(*)=1 from public.commerce_conversion_outbox where provider_payment_id=payment1),'duplicate conversion';
 perform public.analytics_record_payment(paid||jsonb_build_object('status','refunded','refunded_cents',490,'provider_updated_at',now()+interval '1 minute'));
 assert (select status='refunded' from public.user_purchases where user_id=owner_id and item_id=fixture),'refund revokes matching receipt';
 assert (select status='revoked' from public.commerce_conversion_outbox where provider_payment_id=payment1),'refund revokes queued conversion';
 perform public.analytics_record_payment(paid);
 perform public.analytics_record_payment(paid||jsonb_build_object('provider_updated_at',now()+interval '1 minute'));
 perform public.analytics_record_payment(paid||jsonb_build_object('provider_updated_at',now()+interval '2 minutes'));
 assert (select refunded_cents=490 from public.analytics_payments where provider_payment_id=payment1),'refund amount never regresses at equal or later notification timestamps';
 denied:=false;begin update public.user_purchases set status='paid' where user_id=owner_id and item_id=fixture;exception when others then denied:=true;end;assert denied,'stale approval cannot restore reversed receipt';
 perform public.analytics_record_payment(paid||jsonb_build_object('provider_payment_id',payment2,'provider_updated_at',now()+interval '2 minutes'));
 update public.user_purchases set status='paid',provider_payment_id=payment2 where user_id=owner_id and item_id=fixture;
 perform public.analytics_record_payment(paid||jsonb_build_object('status','refunded','refunded_cents',490,'provider_updated_at',now()+interval '3 minutes'));
 assert (select status='paid' and provider_payment_id=payment2 from public.user_purchases where user_id=owner_id and item_id=fixture),'old refund cannot remove later repurchase';
 select target_id into point from public.commerce_products where fulfillment_kind='point' limit 1;
 select count(*) into before_count from public.diagnosis_unlocks where user_id=owner_id;
 insert into public.user_purchases(user_id,item_id,item_type,status,amount_cents,provider,provider_payment_id,purchased_at) values(owner_id,'solution:'||point,'card','paid',990,'manual',null,now()) on conflict(user_id,item_type,item_id) do nothing;
 result:=public.diagnosis_access(owner_id,point,true);assert result->'paid_points' ? point,'point purchase is an entitlement even after draft/deactivation';
 assert (select count(*)=before_count from public.diagnosis_unlocks where user_id=owner_id),'point purchase never spends courtesy';
 result:=public.diagnosis_access(other_id,point,false);assert not (result->'paid_points' ? point),'another account cannot inherit point purchase';
 update public.commerce_products set price_cents=0,category='free',revision=revision+1 where item_id='diagnosis:mercado';
 result:=public.diagnosis_access(other_id,'base.mercado.demanda',false);assert (result->>'allowed')::boolean,'free bundle is accessible without spending courtesy';
 insert into public.analytics_orders(id,user_id,provider_ref,item_id,kind,amount_cents,environment) values(order_id,owner_id,'fixture-contract:'||payment1,'plan:pro','subscription',4790,'test');
 perform public.analytics_record_payment(paid||jsonb_build_object('provider_payment_id','93'||payment1,'order_id',order_id,'item_id','plan:pro','kind','subscription','amount_cents',4790));
 perform public.analytics_record_payment(paid||jsonb_build_object('provider_payment_id','94'||payment1,'order_id',order_id,'item_id','plan:pro','kind','subscription','amount_cents',4790));
 assert (select count(*)=1 from public.commerce_conversion_outbox where event_key='substart:'||order_id::text),'subscription start not repeated on renewal';
 result:=public.commerce_metrics(now()-interval '1 day',now()+interval '1 day','test');assert jsonb_typeof(result->'cards')='array';
 assert exists(select 1 from jsonb_array_elements(result->'cards') x where x->>'item_id'=fixture),'financial report sees verified test journal';
 denied:=false;begin update public.commerce_settings set credit_enabled=true where id='global';exception when others then denied:=true;end;assert denied,'unvalidated first-month credit cannot be activated';
end $$;
rollback;
select 'PASS database: revisions, immutable delivery, RLS, duplicate callbacks, refunds, stale approvals, repurchase, paid-point isolation, courtesy and held credit. All fixtures rolled back.' as result;
